seams.after:
// A directly opened standalone HTML has a file:// origin. Several browsers
// refuse blob: Worklet modules there; the existing XenSonar master Worklet
// already uses a data: module first for the same reason.
load = (async () => {
  const isFile = typeof location !== 'undefined' && location.protocol === 'file:';
  const failures = [];
  const methods = isFile ? ['data', 'blob'] : ['blob', 'data'];
  for (const method of methods) {
    try {
      if (method === 'data') {
        await context.audioWorklet.addModule('data:application/javascript;charset=utf-8,' + encodeURIComponent(source));
      } else {
        if (typeof Blob === 'undefined' || typeof URL === 'undefined' || typeof URL.createObjectURL !== 'function') throw new Error('Blob module URLs unavailable');
        const url = URL.createObjectURL(new Blob([source], {type: 'text/javascript'}));
        try { await context.audioWorklet.addModule(url); }
        finally { URL.revokeObjectURL(url); }
      }
      return;
    } catch (error) { failures.push(method + ': ' + (error?.message ?? String(error))); }
  }
  throw new Error('Nodal-Worklet konnte nicht geladen werden (' + failures.join(' | ') + ')');
})();
modules.set(context, load); load.catch(() => modules.delete(context));
